/**
 ******************************************************************************
 * @file    live_chain_oracle.c
 * TEAM CODE (owner: Tom - sound output and effects) - written by the BJT2 team, not generated by STM32CubeMX.
 * Authors: written by Brendon (integrator) on 29-30 Oct 2026 for Tom's sound output subsystem (best-ui), with an AI coding assistant.
 * @brief   Test oracle: copies of the old live chain's upsampler and effect
 *          loop (the effects are today's AudioEffects).
 *
 * upsample_block() and apply_effects() below are copied from
 * Core/Src/tom_dac_output.c as of 29 Oct 2026 (lines 318-355), with the same
 * static variables. Only two things were left out, because neither ever
 * changed a sample: the DWT cycle timing around each ProcessBlock call and
 * the error counter. Do not "tidy" this file: its whole point is to stay
 * exactly the old code. The effects it calls are today's AudioEffects, so
 * the tests check the chain around the effects (the upsampler, the 64 + 32
 * split, the set-up), not that an effect sounds as it did before: Echo is
 * now 240 ms instead of 120 ms, as asked.
 ******************************************************************************
 */
#include "live_chain_oracle.h"

#include <string.h>

#define ORACLE_HALF_FRAMES 192U     /* TOM_HALF_FRAMES: the old scratch buffers' size */

/* The old TomTask state these functions used (tom_dac_output.c:90-120). */
static AudioEffectsState s_fx;
static uint8_t           s_fx_enabled = 0U;
static int16_t           s_mono48[ORACLE_HALF_FRAMES];
static int16_t           s_fx_out[ORACLE_HALF_FRAMES];
static int16_t           s_last_in = 0;

/* 2:3 linear-interpolation upsampler: n mono samples at 32 kHz -> 3n/2 mono
 * samples at 48 kHz (no gain). Continuity across blocks via s_last_in. */
static uint32_t upsample_block(const int16_t *in, uint32_t n, int16_t *out48)
{
    uint32_t out_n = (n * 3U) / 2U;
    for (uint32_t j = 0; j < out_n; j++) {
        uint32_t u3 = 2U * (j + 1U);
        uint32_t i  = u3 / 3U;
        uint32_t f3 = u3 % 3U;
        int32_t a = (i == 0U) ? s_last_in : in[i - 1U];
        int32_t b = (i >= n) ? in[n - 1U] : in[i];
        out48[j] = (int16_t)(a + (((b - a) * (int32_t)f3) / 3));
    }
    s_last_in = in[n - 1U];
    return out_n;
}

/* Run the selected effect over m samples at 48 kHz in <= 64-sample calls.
 * On any error the chunk is passed through. (DWT timing and the error
 * counter left out.) */
static const int16_t *apply_effects(const int16_t *in48, uint32_t m)
{
    if (!s_fx_enabled) return in48;
    uint32_t done = 0U;
    while (done < m) {
        uint32_t chunk = m - done;
        if (chunk > AUDIO_EFFECTS_MAX_BLOCK_SIZE) chunk = AUDIO_EFFECTS_MAX_BLOCK_SIZE;
        AudioEffectsStatus st = AudioEffects_ProcessBlock(&s_fx, &in48[done], &s_fx_out[done], chunk);
        if (st != AUDIO_EFFECTS_STATUS_OK) {
            memcpy(&s_fx_out[done], &in48[done], chunk * sizeof(int16_t));
        }
        done += chunk;
    }
    return s_fx_out;
}

void Oracle_UpsamplerReset(void)
{
    s_last_in = 0;
}

uint32_t Oracle_UpsampleBlock(const int16_t *in_32k, uint32_t n, int16_t *out_48k)
{
    return upsample_block(in_32k, n, out_48k);      /* n >= 1: the old code read in[n - 1] */
}

void Oracle_LiveChainBegin(AudioEffectMode mode)
{
    memset(&s_fx, 0, sizeof(s_fx));                 /* TomTask's s_fx was all zeros in .bss at boot */
    AudioEffects_Init(&s_fx);                       /* Tom_Init (tom_dac_output.c:618) */
    (void)AudioEffects_SetMode(&s_fx, mode);        /* set_effect (:500) */
    AudioEffects_Reset(&s_fx);                      /* set_effect (:505) */
    s_fx_enabled = 1U;                              /* set_effect (:506) */
    s_last_in = 0;                                  /* TOM_CMD_SOURCE_PLAYBACK (:580) */
    AudioEffects_Reset(&s_fx);                      /* TOM_CMD_SOURCE_PLAYBACK (:581) */
}

/* render_block_frames() (:358-369) without the volume gain and the L/R
 * interleave, which come after the effect and are not part of the file. */
uint32_t Oracle_LiveChainBlock(const int16_t *in_32k, uint32_t n, int16_t *out_48k)
{
    uint32_t m = upsample_block(in_32k, n, s_mono48);
    const int16_t *src = apply_effects(s_mono48, m);
    memcpy(out_48k, src, m * sizeof(int16_t));
    return m;
}
